-- Parity test for Cognos report Customer_Billing_Summary (cluster BIL_001, 24 runs/day)
-- Generated by SemanticLift 1.0.0; tolerance +/-0.5% on totals
WITH cognos AS (
    SELECT billing.DUE_DATE AS due_date, billing.PAYMENT_STATUS AS payment_status, dt.FISCAL_YEAR AS fiscal_year, dt.FULL_DATE AS full_date, dt.MONTH_NAME AS month_name, customer.CUSTOMER_NAME AS customer_name, customer.CUSTOMER_SEGMENT AS customer_segment, location.CITY AS city, location.REGION AS region, SUM(billing.BILL_AMOUNT) AS total_bill_amount, SUM(billing.DEMAND_CHARGE) AS total_demand_charge, SUM(billing.TAX_AMOUNT) AS total_tax_amount
    FROM CORE.FCT_BILLING billing
    JOIN CORE.DIM_DATE dt ON billing.DATE_KEY = dt.DATE_KEY
    JOIN CORE.DIM_METER meter ON billing.METER_ID = meter.METER_ID
    JOIN CORE.DIM_CUSTOMER customer ON meter.CUSTOMER_ID = customer.CUSTOMER_ID
    JOIN CORE.DIM_LOCATION location ON meter.LOCATION_ID = location.LOCATION_ID
    WHERE dt.FISCAL_YEAR = 2026
    GROUP BY 1, 2, 3, 4, 5, 6, 7, 8, 9
),
semantic AS (
    SELECT * FROM SEMANTIC_VIEW(
        SEM.SV_BILLING_REVENUE
        DIMENSIONS billing.due_date, billing.payment_status, dt.fiscal_year, dt.full_date, dt.month_name, customer.customer_name, customer.customer_segment, location.city, location.region
        METRICS billing.total_bill_amount, billing.total_demand_charge, billing.total_tax_amount
    ) WHERE fiscal_year = 2026
)
SELECT
    (SELECT COUNT(*) FROM cognos) AS cognos_rows,
    (SELECT COUNT(*) FROM semantic) AS semantic_rows,
    SUM(c.total_bill_amount) AS cognos_total_bill_amount, SUM(s.total_bill_amount) AS semantic_total_bill_amount,
    IFF(ABS(COALESCE(SUM(s.total_bill_amount), 0) - COALESCE(SUM(c.total_bill_amount), 0)) <= 0.5 / 100 * ABS(NULLIF(SUM(c.total_bill_amount), 0)), 'PASS', 'FAIL') AS status_total_bill_amount,
    SUM(c.total_demand_charge) AS cognos_total_demand_charge, SUM(s.total_demand_charge) AS semantic_total_demand_charge,
    IFF(ABS(COALESCE(SUM(s.total_demand_charge), 0) - COALESCE(SUM(c.total_demand_charge), 0)) <= 0.5 / 100 * ABS(NULLIF(SUM(c.total_demand_charge), 0)), 'PASS', 'FAIL') AS status_total_demand_charge,
    SUM(c.total_tax_amount) AS cognos_total_tax_amount, SUM(s.total_tax_amount) AS semantic_total_tax_amount,
    IFF(ABS(COALESCE(SUM(s.total_tax_amount), 0) - COALESCE(SUM(c.total_tax_amount), 0)) <= 0.5 / 100 * ABS(NULLIF(SUM(c.total_tax_amount), 0)), 'PASS', 'FAIL') AS status_total_tax_amount
FROM cognos c
FULL OUTER JOIN semantic s ON c.due_date IS NOT DISTINCT FROM s.due_date AND c.payment_status IS NOT DISTINCT FROM s.payment_status AND c.fiscal_year IS NOT DISTINCT FROM s.fiscal_year AND c.full_date IS NOT DISTINCT FROM s.full_date AND c.month_name IS NOT DISTINCT FROM s.month_name AND c.customer_name IS NOT DISTINCT FROM s.customer_name AND c.customer_segment IS NOT DISTINCT FROM s.customer_segment AND c.city IS NOT DISTINCT FROM s.city AND c.region IS NOT DISTINCT FROM s.region;
